	}
	if len(got) != len(want) {
		t.Fatalf("node %q history has %d records, want %d: %+v", node, len(got), len(want), got)
	}
	for i := range want {
		if !got[i].Equal(want[i]) {
			t.Errorf("node %q record %d = %+v, want %+v", node, i, got[i], want[i])
