3	// Cross-process regression tests for concurrent `heartbeat submit`.
4	//
5	// The in-package TestConcurrentSubmit* tests exercise many Store instances in
6	// one process (many goroutines, one address space). These tests cover the
7	// operational situation described by the product: after a node reconnects,
8	// the same cached heartbeat may be delivered by two independent submitting
9	// processes at once. Every request here is therefore a separate OS process
10	// running the genuine command entry point through TestMain — flag parsing,
11	// stdin decoding, the real cross-process flock, stdout/stderr placement and
12	// the process exit status are all part of what is verified.
13	//
14	// The two processes are released together from a stdin start gate, so they
15	// genuinely contend for the same data directory lock; but every assertion
16	// below holds for ANY lock-acquisition order and classifies results by the
17	// requests' actual output and exit status, so the tests never assume which
18	// request "wins" and cannot flake on scheduling. All collection and receive
19	// instants are fixed; no judgement depends on the day or time the tests run.
20	
21	import (
22		"errors"
23		"fmt"
24		"os"
25		"os/exec"
26		"path/filepath"
27		"strings"
28		"sync"
29		"testing"
30		"time"
31	)
32	
33	const (
34		concNode = "val-eu-1"
35	
36		// Fixed business instants. concAt7UTC and concAt7CN name the SAME instant
37		// in different timezones; concAt8UTC is a later heartbeat of the same node.
38		concAt7UTC = "2026-10-01T11:59:00Z"
39		concAt7CN  = "2026-10-01T19:59:00+08:00"
40		concAt8UTC = "2026-10-01T11:59:30Z"
41	
42		concV1 = "1.26.0"
43		concV2 = "1.27.0"
44	
45		concH7 = 12345
46		concH8 = 12346
47	
48		concMissed7 = 3
49		concMissed8 = 4
50	
51		// concRounds repeats each race against a fresh data directory so both
52		// lock-acquisition orders are exercised in practice across a run.
53		concRounds = 8
54	)
55	
56	// concResult is everything observable about one submitting process.
57	type concResult struct {
58		out    string // stdout, trailing newline trimmed
59		errOut string // stderr, trailing newline trimmed
60		code   int    // process exit status
61	}
62	
63	// concRecordJSON builds one strict heartbeat object from fixed-value parts.
64	// Every value is plain ASCII-safe text, so Go quoting and JSON quoting agree.
65	func concRecordJSON(node string, seq int, collected, version string, height, missed int) string {
66		return fmt.Sprintf(
67			`{"node":%q,"seq":%d,"collected_at":%q,"version":%q,"height":%d,"missed":%d}`,
68			node, seq, collected, version, height, missed)
69	}
70	
71	// concHistoryLine is the exact public history line for one of the fixed
72	// records: node=%s seq=%d collected_at=%s version=%s height=%d missed=%d.
73	func concHistoryLine(seq int, collected, version string, height, missed int) string {
74		return fmt.Sprintf("node=%s seq=%d collected_at=%s version=%s height=%d missed=%d",
75			concNode, seq, collected, version, height, missed)
76	}
77	
78	func concSubmittedLine(newCount, dupCount int) string {
79		return fmt.Sprintf("submitted: new=%d duplicate=%d", newCount, dupCount)
80	}
81	
82	// runConcurrentSubmitPair launches two independent helper processes that both
83	// run the real `heartbeat submit` command against the same data directory,
84	// each with its own payload on its own stdin.
85	//
86	// Each process is handed the read end of an os.Pipe as stdin and parks in
87	// io.ReadAll(os.Stdin) — before parsing input or opening the store. The write
88	// ends stay in this test process until both processes have started, then both
89	// payloads are written and closed at once, which is the start gate: the two
90	// genuine processes parse, open the store and contend on the cross-process
91	// flock together. The short pre-gate wait only lets both processes reach the
92	// gate; it is not used in any business assertion (and a shorter or longer
93	// wait cannot change the expected outcome, which is order-independent).
94	func runConcurrentSubmitPair(t *testing.T, dir, payloadA, payloadB string) [2]concResult {
95		t.Helper()
96	
97		payloads := [][]byte{[]byte(payloadA), []byte(payloadB)}
98		pipes := make([]*os.File, 2)
99		cmds := make([]*exec.Cmd, 2)
100		var stdoutBuf, stderrBuf [2]strings.Builder
101	
102		for i := range payloads {
103			r, w, err := os.Pipe()
104			if err != nil {
105				t.Fatalf("create stdin pipe: %v", err)
106			}
107			pipes[i] = w
108	
109			cmd := exec.Command(os.Args[0],
110				"heartbeat", "submit", "--data-dir", dir, "--receive-time", cliReceiveAt)
111			cmd.Stdin = r
112			cmd.Stdout = &stdoutBuf[i]
113			cmd.Stderr = &stderrBuf[i]
114			// Same environment contract as the serial CLI helper: HOME and the
115			// data-dir env var are confined to the temp directory, and the re-exec
116			// marker makes the test binary run main() itself.
117			cmd.Env = append(os.Environ(),
118				cliTestEnv+"=1",
119				"HOME="+dir,
120				"EDGEFLEET_DATA_DIR="+filepath.Join(dir, "env-data"),
121			)
122			cmds[i] = cmd
123	
124			// Avoid leaking a parked process if a later start or assertion aborts.
125			t.Cleanup(func() {
126				if cmd.Process != nil && cmd.ProcessState == nil {
127					_ = cmd.Process.Kill()
128				}
129				_ = r.Close()
130				_ = w.Close()
131			})
132		}
133	
134		for i, cmd := range cmds {
135			if err := cmd.Start(); err != nil {
136				t.Fatalf("start helper process %d: %v", i, err)
137			}
138		}
139	
140		// Both processes are reaching io.ReadAll(stdin); give the slower starter
141		// time to park there, then release the pair simultaneously.
142		time.Sleep(100 * time.Millisecond)
143		var wg sync.WaitGroup
144		for i := range payloads {
145			wg.Add(1)
146			go func(i int) {
147				defer wg.Done()
148				if _, err := pipes[i].Write(payloads[i]); err != nil {
149					t.Errorf("feed payload to process %d: %v", i, err)
150				}
151				_ = pipes[i].Close() // EOF releases the process's ReadAll
152			}(i)
153		}
154		wg.Wait()
155	
156		var results [2]concResult
157		for i, cmd := range cmds {
158			if err := cmd.Wait(); err != nil {
159				var exitErr *exec.ExitError
160				if !errors.As(err, &exitErr) {
161					t.Fatalf("helper process %d failed to run: %v", i, err)
162				}
163				results[i].code = exitErr.ExitCode()
164			}
165			results[i].out = strings.TrimRight(stdoutBuf[i].String(), "\n")
166			results[i].errOut = strings.TrimRight(stderrBuf[i].String(), "\n")
167		}
168		return results
169	}
170	
171	// assertSubmitSuccess locks the public success contract for one submitting
172	// process: exit status zero, nothing on stderr, and the exact counters line.
173	func assertSubmitSuccess(t *testing.T, who string, r concResult, wantLine string) {
174		t.Helper()
175		if r.code != 0 {
176			t.Errorf("%s: expected success, exit=%d stderr=%q stdout=%q", who, r.code, r.errOut, r.out)
177		}
178		if r.errOut != "" {
179			t.Errorf("%s: successful submit must print no error output, stderr=%q", who, r.errOut)
180		}
181		if r.out != wantLine {
182			t.Errorf("%s: stdout=%q, want %q", who, r.out, wantLine)
183		}
184	}
185	
186	// assertConflictFailure locks the public conflict contract: non-zero exit, an
187	// error on stderr that identifies both the node and the seq, and no success
188	// line or counters on stdout (nothing may look like a committed submission).
189	func assertConflictFailure(t *testing.T, who string, r concResult) {
190		t.Helper()
191		if r.code == 0 {
192			t.Errorf("%s: conflicting submit must exit non-zero; stdout=%q stderr=%q", who, r.out, r.errOut)
193		}
194		if strings.Contains(r.out, "submitted") || strings.Contains(r.out, "new=") {
195			t.Errorf("%s: rejected submit must not report success or new counts, stdout=%q", who, r.out)
196		}
197		for _, want := range []string{"error:", "conflict", concNode, "seq 7"} {
198			if !strings.Contains(r.errOut, want) {
199				t.Errorf("%s: stderr must contain %q to identify the clash, got %q", who, want, r.errOut)
200			}
201		}
202	}
203	
204	// exactlyOneSuccess reports which of the two processes succeeded, failing the
205	// test unless the split is exactly one winner and one loser.
206	func exactlyOneSuccess(t *testing.T, res [2]concResult) (winner, loser int) {
207		t.Helper()
208		switch {
209		case res[0].code == 0 && res[1].code != 0:
210			return 0, 1
211		case res[1].code == 0 && res[0].code != 0:
212			return 1, 0
213		default:
214			t.Fatalf("exactly one request must succeed, got exit codes %d and %d; stdout %q / %q; stderr %q / %q",
215				res[0].code, res[1].code, res[0].out, res[1].out, res[0].errOut, res[1].errOut)
216			return 0, 0
217		}
218	}
219	
220	// TestCLIConcurrentProcessesSameRecordOneNewOneDuplicate is the reconnect
221	// case: while the target record is not saved yet, two processes each deliver
222	// the very same cached heartbeat. Both requests succeed, but across the pair
223	// there is exactly one new record and one duplicate; each request's own
224	// counters match that split. History afterwards contains the node+seq once,
225	// with every submitted field intact.
226	func TestCLIConcurrentProcessesSameRecordOneNewOneDuplicate(t *testing.T) {
227		payload := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV1, concH7, concMissed7) + "]"
228		wantHistory := concHistoryLine(7, concAt7UTC, concV1, concH7, concMissed7)
229	
230		for round := 0; round < concRounds; round++ {
231			t.Run(fmt.Sprintf("round-%02d", round+1), func(t *testing.T) {
232				dir := t.TempDir()
233				res := runConcurrentSubmitPair(t, dir, payload, payload)
234	
235				for i, r := range res {
236					if r.code != 0 {
237						t.Errorf("request %d: an identical repeat must succeed, exit=%d stderr=%q", i, r.code, r.errOut)
238					}
239					if r.errOut != "" {
240						t.Errorf("request %d: an identical repeat must produce no error output, stderr=%q", i, r.errOut)
241					}
242				}
243	
244				// One request saw the record absent and saved it; the other saw it
245				// present and counted a duplicate. The two outcomes must split 1/1.
246				bothNew := res[0].out == concSubmittedLine(1, 0) && res[1].out == concSubmittedLine(1, 0)
247				bothDup := res[0].out == concSubmittedLine(0, 1) && res[1].out == concSubmittedLine(0, 1)
248				if bothNew || bothDup {
249					t.Fatalf("expected one new and one duplicate across the pair, got %q and %q", res[0].out, res[1].out)
250				}
251				for i, r := range res {
252					if r.out != concSubmittedLine(1, 0) && r.out != concSubmittedLine(0, 1) {
253						t.Errorf("request %d: unexpected counters %q", i, r.out)
254					}
255				}
256	
257				lines := historyLines(t, dir, concNode)
258				if len(lines) != 1 {
259					t.Fatalf("history must hold the node+seq exactly once, got %d lines: %q", len(lines), lines)
260				}
261				if lines[0] != wantHistory {
262					t.Errorf("saved record differs from the submitted one:\n got %q\nwant %q", lines[0], wantHistory)
263				}
264			})
265		}
266	}
267	
268	// TestCLIConcurrentProcessesSameInstantDifferentOffsetIsDuplicate pins the
269	// time semantics across processes: the same collection instant written in
270	// different timezones is the same record. The different-looking strings must
271	// not be treated as a conflict, no error output is allowed, and history keeps
272	// one record whose instant equals the submitted moment (its timezone spelling
273	// is whichever request happened to save it first).
274	func TestCLIConcurrentProcessesSameInstantDifferentOffsetIsDuplicate(t *testing.T) {
275		recUTC := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV1, concH7, concMissed7) + "]"
276		recCN := "[" + concRecordJSON(concNode, 7, concAt7CN, concV1, concH7, concMissed7) + "]"
277		wantInstant, err := time.Parse(time.RFC3339, concAt7UTC)
278		if err != nil {
279			t.Fatal(err)
280		}
281	
282		for round := 0; round < concRounds; round++ {
283			t.Run(fmt.Sprintf("round-%02d", round+1), func(t *testing.T) {
284				dir := t.TempDir()
285	
286				// Swap sides each round so either spelling can be first saved.
287				payloadA, spellingA := recUTC, concAt7UTC
288				payloadB, spellingB := recCN, concAt7CN
289				if round%2 == 1 {
290					payloadA, spellingA, payloadB, spellingB = recCN, concAt7CN, recUTC, concAt7UTC
291				}
292	
293				res := runConcurrentSubmitPair(t, dir, payloadA, payloadB)
294				for i, r := range res {
295					if r.code != 0 {
296						t.Errorf("request %d: timezone-equal repeat must succeed, exit=%d stderr=%q", i, r.code, r.errOut)
297					}
298					if r.errOut != "" {
299						t.Errorf("request %d: timezone-equal repeat must produce no error output, stderr=%q", i, r.errOut)
300					}
301					if r.out != concSubmittedLine(1, 0) && r.out != concSubmittedLine(0, 1) {
302						t.Errorf("request %d: unexpected counters %q", i, r.out)
303					}
304				}
305				if (res[0].out == concSubmittedLine(1, 0)) == (res[1].out == concSubmittedLine(1, 0)) {
306					t.Fatalf("expected one new and one duplicate, got %q and %q", res[0].out, res[1].out)
307				}
308	
309				lines := historyLines(t, dir, concNode)
310				if len(lines) != 1 {
311					t.Fatalf("timezone-equal records must collapse to one, got %q", lines)
312				}
313				// The saved spelling belongs to the request that saved it; the
314				// instant must be identical regardless of which spelling won.
315				wantSpelling := spellingA
316				if res[1].out == concSubmittedLine(1, 0) {
317					wantSpelling = spellingB
318				}
319				if want := concHistoryLine(7, wantSpelling, concV1, concH7, concMissed7); lines[0] != want {
320					t.Errorf("history line:\n got %q\nwant %q", lines[0], want)
321				}
322				fields := strings.Fields(lines[0])
323				gotInstant, perr := time.Parse(time.RFC3339, strings.TrimPrefix(fields[2], "collected_at="))
324				if perr != nil {
325					t.Fatalf("saved collected_at is not RFC3339: %q", fields[2])
326				}
327				if !gotInstant.Equal(wantInstant) {
328					t.Errorf("saved instant %s != submitted instant %s", gotInstant.Format(time.RFC3339), wantInstant.Format(time.RFC3339))
329				}
330			})
331		}
332	}
333	
334	// TestCLIConcurrentProcessesDifferentVersionConflicts covers two records of
335	// the same node+seq whose versions differ. Exactly one request succeeds; the
336	// other must exit non-zero with a conflict error naming node and seq and must
337	// print no success or new-count output. Either version may be saved first;
338	// history must then contain exactly the winning request's record, never
339	// overwritten by the loser.
340	func TestCLIConcurrentProcessesDifferentVersionConflicts(t *testing.T) {
341		recV1 := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV1, concH7, concMissed7) + "]"
342		recV2 := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV2, concH7, concMissed7) + "]"
343	
344		for round := 0; round < concRounds; round++ {
345			t.Run(fmt.Sprintf("round-%02d", round+1), func(t *testing.T) {
346				dir := t.TempDir()
347	
348				// Swap sides each round so both versions genuinely experience both
349				// outcomes; expectations follow the observed winner.
350				payloadA, versionA := recV1, concV1
351				payloadB, versionB := recV2, concV2
352				if round%2 == 1 {
353					payloadA, versionA, payloadB, versionB = recV2, concV2, recV1, concV1
354				}
355	
356				res := runConcurrentSubmitPair(t, dir, payloadA, payloadB)
357				winner, loser := exactlyOneSuccess(t, res)
358				assertSubmitSuccess(t, "winning request", res[winner], concSubmittedLine(1, 0))
359				assertConflictFailure(t, "losing request", res[loser])
360	
361				winningVersion := versionA
362				if winner == 1 {
363					winningVersion = versionB
364				}
365				lines := historyLines(t, dir, concNode)
366				if len(lines) != 1 {
367					t.Fatalf("conflict must leave exactly one saved record, got %q", lines)
368				}
369				want := concHistoryLine(7, concAt7UTC, winningVersion, concH7, concMissed7)
370				if lines[0] != want {
371					t.Errorf("history must match the winner exactly:\n got %q\nwant %q (loser must not overwrite)", lines[0], want)
372				}
373			})
374		}
375	}
376	
377	// TestCLIConcurrentProcessesConflictRejectsWholeBatch adds the batch rule:
378	// when the losing request also carries a legal record for another seq of the
379	// same node, that companion record must not be saved either — a conflict
380	// rejects the whole batch. If the two-record batch wins instead, both of its
381	// records persist and the single-record request loses; history in that case
382	// holds both seqs in ascending order with the batch's version on each.
383	func TestCLIConcurrentProcessesConflictRejectsWholeBatch(t *testing.T) {
384		// Single-record request: seq 7 on version 1.26.0.
385		single := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV1, concH7, concMissed7) + "]"
386		// Batch request: clashing seq 7 (version 1.27.0) plus a legal seq 8.
387		batch := "[" +
388			concRecordJSON(concNode, 7, concAt7UTC, concV2, concH7, concMissed7) + "," +
389			concRecordJSON(concNode, 8, concAt8UTC, concV2, concH8, concMissed8) + "]"
390	
391		for round := 0; round < concRounds; round++ {
392			t.Run(fmt.Sprintf("round-%02d", round+1), func(t *testing.T) {
393				dir := t.TempDir()
394	
395				// Swap which process carries which request; the outcome follows the
396				// content, not the process position.
397				payloadA, payloadB := single, batch
398				batchIdx, singleIdx := 1, 0 // process A carries the single record, B the batch
399				if round%2 == 1 {
400					payloadA, payloadB = batch, single
401					batchIdx, singleIdx = 0, 1
402				}
403	
404				res := runConcurrentSubmitPair(t, dir, payloadA, payloadB)
405	
406				lines := historyLines(t, dir, concNode)
407				switch {
408				case res[singleIdx].code == 0 && res[batchIdx].code != 0:
409					// The single seq-7 record won; the whole clashing batch was
410					// rejected, so its otherwise-valid seq 8 must not exist.
411					assertSubmitSuccess(t, "single-record request", res[singleIdx], concSubmittedLine(1, 0))
412					assertConflictFailure(t, "clashing batch request", res[batchIdx])
413					if len(lines) != 1 {
414						t.Fatalf("rejected batch must leave no companion record, got %q", lines)
415					}
416					want := concHistoryLine(7, concAt7UTC, concV1, concH7, concMissed7)
417					if lines[0] != want {
418						t.Errorf("surviving record:\n got %q\nwant %q", lines[0], want)
419					}
420	
421				case res[batchIdx].code == 0 && res[singleIdx].code != 0:
422					// The batch won: both its records are saved and the single
423					// request loses the seq-7 clash.
424					assertSubmitSuccess(t, "batch request", res[batchIdx], concSubmittedLine(2, 0))
425					assertConflictFailure(t, "single-record request", res[singleIdx])
426					if len(lines) != 2 {
427						t.Fatalf("winning batch must save both records, got %q", lines)
428					}
429					want7 := concHistoryLine(7, concAt7UTC, concV2, concH7, concMissed7)
430					want8 := concHistoryLine(8, concAt8UTC, concV2, concH8, concMissed8)
431					if lines[0] != want7 || lines[1] != want8 {
432						t.Errorf("history must be ascending and match the batch:\n got %q / %q\nwant %q / %q",
433							lines[0], lines[1], want7, want8)
434					}
435	
436				default:
437					t.Fatalf("exactly one side must succeed, got exits single=%d batch=%d; stderr %q / %q",
438						res[singleIdx].code, res[batchIdx].code, res[singleIdx].errOut, res[batchIdx].errOut)
439				}
440			})
441		}
442	}
443	
444	// TestCLIConcurrentProcessesDifferentSeqsBothKept checks that parallel
445	// submissions of different seqs for the same node do not lose each other's
446	// new records: both requests succeed with one new record each, and history
447	// returns both in ascending seq order with their own submitted content.
448	func TestCLIConcurrentProcessesDifferentSeqsBothKept(t *testing.T) {
449		rec7 := "[" + concRecordJSON(concNode, 7, concAt7UTC, concV1, concH7, concMissed7) + "]"
450		rec8 := "[" + concRecordJSON(concNode, 8, concAt8UTC, concV1, concH8, concMissed8) + "]"
451	
452		for round := 0; round < concRounds; round++ {
453			t.Run(fmt.Sprintf("round-%02d", round+1), func(t *testing.T) {
454				dir := t.TempDir()
455	
456				payloadA, payloadB := rec7, rec8
457				if round%2 == 1 {
458					payloadA, payloadB = rec8, rec7
459				}
460				res := runConcurrentSubmitPair(t, dir, payloadA, payloadB)
461	
462				for i, r := range res {
463					assertSubmitSuccess(t, fmt.Sprintf("request %d", i), r, concSubmittedLine(1, 0))
464				}
465	
466				lines := historyLines(t, dir, concNode)
467				if len(lines) != 2 {
468					t.Fatalf("both parallel inserts must survive, got %d lines: %q", len(lines), lines)
469				}
470				want7 := concHistoryLine(7, concAt7UTC, concV1, concH7, concMissed7)
471				want8 := concHistoryLine(8, concAt8UTC, concV1, concH8, concMissed8)
472				if lines[0] != want7 {
473					t.Errorf("first history line:\n got %q\nwant %q", lines[0], want7)
474				}
475				if lines[1] != want8 {
476					t.Errorf("second history line:\n got %q\nwant %q", lines[1], want8)
477				}
478			})
479		}
480	}
