33	func TestParseHeartbeatsValid(t *testing.T) {
34		input := `[
35		  {"node":"val-1","seq":1,"collected_at":"2026-10-01T11:59:00Z","version":"1.0.0","height":100,"missed":0},
36		  {"node":"val-2","seq":2,"collected_at":"2026-10-01T20:00:00+08:00","version":"1.0.0","height":101,"missed":1}
37		]`
38		records, err := ParseHeartbeats([]byte(input), testBase)
39		if err != nil {
40			t.Fatalf("unexpected error: %v", err)
41		}
42		if len(records) != 2 {
43			t.Fatalf("expected 2 records, got %d", len(records))
44		}
45		if records[0].NodeID != "val-1" || records[0].Seq != 1 || records[0].Height != 100 || records[0].Missed != 0 {
46			t.Errorf("record 0 mismatch: %+v", records[0])
47		}
48		// +08:00 20:00 is 12:00 UTC, equal to testBase -> valid (not later than receive).
49		if !records[1].CollectedAt.Equal(testBase) {
50			t.Errorf("record 1 time = %v, want %v", records[1].CollectedAt, testBase)
51		}
52	}
