105	func TestValidateHeartbeat(t *testing.T) {
106		receive := testBase
107		valid := hb("n1", 1, receive.Add(-time.Minute), "1.0", 10, 0)
108		if err := ValidateHeartbeat(valid, receive); err != nil {
109			t.Errorf("valid record rejected: %v", err)
110		}
111		// Boundary: collected exactly at receive time is allowed.
112		exact := hb("n1", 1, receive, "1.0", 10, 0)
113		if err := ValidateHeartbeat(exact, receive); err != nil {
114			t.Errorf("collected_at == receive_time should be allowed: %v", err)
115		}
116		// Boundary: height 0 and missed 0 are allowed.
117		zero := hb("n1", 1, receive.Add(-time.Minute), "1.0", 0, 0)
118		if err := ValidateHeartbeat(zero, receive); err != nil {
119			t.Errorf("zero height/missed should be allowed: %v", err)
120		}
121		// Future collection time rejected.
122		future := hb("n1", 1, receive.Add(time.Second), "1.0", 10, 0)
123		if err := ValidateHeartbeat(future, receive); err == nil {
124			t.Errorf("future collected_at should be rejected")
125		}
126	}
