128	func TestSubmitNewAndDuplicate(t *testing.T) {
129		store, err := OpenStore(t.TempDir())
130		if err != nil {
131			t.Fatal(err)
132		}
133		receive := testBase
134		batch := []Heartbeat{
135			hb("n1", 1, receive.Add(-2*time.Minute), "1.0", 100, 0),
136			hb("n1", 2, receive.Add(-time.Minute), "1.0", 101, 0),
137			hb("n2", 5, receive.Add(-time.Minute), "2.0", 50, 3),
138		}
139		newC, dupC, err := store.Submit(batch, receive)
140		if err != nil {
141			t.Fatalf("submit failed: %v", err)
142		}
143		if newC != 3 || dupC != 0 {
144			t.Errorf("first submit: new=%d dup=%d, want 3/0", newC, dupC)
145		}
146	
147		// Re-submit the same records: all duplicates, nothing new.
148		newC, dupC, err = store.Submit(batch, receive)
149		if err != nil {
150			t.Fatalf("resubmit failed: %v", err)
151		}
152		if newC != 0 || dupC != 3 {
153			t.Errorf("resubmit: new=%d dup=%d, want 0/3", newC, dupC)
154		}
155	
156		// Same instant expressed in a different timezone is still a duplicate.
157		rebased := []Heartbeat{hb("n1", 1, receive.Add(-2*time.Minute).In(time.FixedZone("+08", 8*3600)), "1.0", 100, 0)}
158		newC, dupC, err = store.Submit(rebased, receive)
159		if err != nil {
160			t.Fatalf("rebased submit failed: %v", err)
161		}
162		if newC != 0 || dupC != 1 {
163			t.Errorf("rebased: new=%d dup=%d, want 0/1", newC, dupC)
164		}
165	}
