291		if err != nil {
292			t.Fatal(err)
293		}
294		if len(hist) != 3 {
295			t.Fatalf("expected 3 records, got %d", len(hist))
296		}
297		for i, wantSeq := range []int64{1, 3, 5} {
298			if hist[i].Seq != wantSeq {
299				t.Errorf("position %d: seq=%d, want %d", i, hist[i].Seq, wantSeq)
300			}
301		}
302	
303		// Late record with a smaller seq still gets saved.
304		late := hb("n1", 2, receive.Add(-4*time.Minute), "1.0", 102, 0)
