309		if len(hist) != 4 || hist[1].Seq != 2 {
310			t.Errorf("late record not inserted in order: %+v", hist)
311		}
312	
313		// Current telemetry is always the max seq.
314		result, err := store.Health("n1", receive, "1.0", 0)
315		if err != nil {
316			t.Fatal(err)
317		}
318		if result.Seq != 5 || result.Height != 105 {
