625	func TestConcurrentSubmitConflict(t *testing.T) {
626		dir := t.TempDir()
627		receive := testBase
628		r1 := hb("n1", 1, receive.Add(-time.Minute), "1.0", 100, 0)
629		r2 := hb("n1", 1, receive.Add(-time.Minute), "2.0", 100, 0)
630	
631		var mu sync.Mutex
632		successes := 0
633		conflicts := 0
634		var errs []error
635		var wg sync.WaitGroup
636		for i := 0; i < 20; i++ {
637			wg.Add(1)
638			go func(i int) {
639				defer wg.Done()
640				store, err := OpenStore(dir)
641				if err != nil {
642					mu.Lock()
643					errs = append(errs, err)
644					mu.Unlock()
645					return
646				}
647				r := r1
648				if i%2 == 1 {
649					r = r2
650				}
651				_, _, err = store.Submit([]Heartbeat{r}, receive)
652				mu.Lock()
653				if err == nil {
654					successes++
655				} else if strings.Contains(err.Error(), "conflict") {
656					conflicts++
657				} else {
658					errs = append(errs, err)
659				}
660				mu.Unlock()
661			}(i)
662		}
663		wg.Wait()
664		if len(errs) != 0 {
665			t.Fatalf("unexpected errors: %v", errs)
666		}
667		// All 10 submissions of the winning variant succeed (1 new + 9
668		// duplicates); all 10 of the losing variant hit the conflict.
669		if successes != 10 {
670			t.Errorf("successes=%d, want 10", successes)
671		}
672		if conflicts != 10 {
673			t.Errorf("conflicts=%d, want 10", conflicts)
674		}
675		// The stored record is one of the two, intact.
676		store, err := OpenStore(dir)
677		if err != nil {
678			t.Fatal(err)
679		}
680		hist, err := store.History("n1")
681		if err != nil {
682			t.Fatal(err)
683		}
684		if len(hist) != 1 || (hist[0].Version != "1.0" && hist[0].Version != "2.0") {
685			t.Errorf("stored record invalid: %+v", hist)
686		}
687	}
