689	func TestConcurrentQuerySeesConsistentState(t *testing.T) {
690		dir := t.TempDir()
691		receive := testBase
692	
693		var submittedMu sync.Mutex
694		submitted := map[int64]bool{}
695		var wg sync.WaitGroup
696	
697		// Writers: each batch adds 5 new seqs.
698		for w := 0; w < 4; w++ {
699			wg.Add(1)
700			go func(w int) {
701				defer wg.Done()
702				store, err := OpenStore(dir)
703				if err != nil {
704					t.Error(err)
705					return
706				}
707				batch := make([]Heartbeat, 5)
708				for j := 0; j < 5; j++ {
709					seq := int64(w*5 + j + 1)
710					batch[j] = hb("n1", seq, receive.Add(-time.Duration(100-seq)*time.Second), "1.0", seq, 0)
711				}
712				if _, _, err := store.Submit(batch, receive); err != nil {
713					t.Error(err)
714					return
715				}
716				submittedMu.Lock()
717				for _, r := range batch {
718					submitted[r.Seq] = true
719				}
720				submittedMu.Unlock()
721			}(w)
722		}
723	
724		// Readers: history must always be sorted, duplicate-free, and only
725		// contain seqs that have been submitted.
726		for r := 0; r < 8; r++ {
727			wg.Add(1)
728			go func() {
729				defer wg.Done()
730				store, err := OpenStore(dir)
731				if err != nil {
732					t.Error(err)
733					return
734				}
735				for i := 0; i < 50; i++ {
736					hist, err := store.History("n1")
737					if err != nil {
738						t.Error(err)
739						return
740					}
741					var prev int64
742					seen := map[int64]bool{}
743					for _, r := range hist {
744						if r.Seq <= prev && prev != 0 {
745							t.Errorf("history not sorted: %+v", hist)
746							return
747						}
748						if seen[r.Seq] {
749							t.Errorf("duplicate seq in history: %d", r.Seq)
750							return
751						}
752						seen[r.Seq] = true
753						prev = r.Seq
754						submittedMu.Lock()
755						ok := submitted[r.Seq]
756						submittedMu.Unlock()
757						if !ok {
758							t.Errorf("history contains seq %d that was never submitted", r.Seq)
759							return
760						}
761					}
762				}
763			}()
764		}
765		wg.Wait()
766	
767		// Final state: all 20 records present.
768		store, _ := OpenStore(dir)
769		hist, err := store.History("n1")
770		if err != nil {
771			t.Fatal(err)
772		}
773		if len(hist) != 20 {
774			t.Errorf("final history count=%d, want 20", len(hist))
775		}
776	}
