package edgefleet

import (
	"sync"
	"testing"
	"time"
)

// SCRATCH verification (deleted after the run): emulate a BROKEN store that
// commits a multi-record backfill one new record at a time as separate atomic
// file replacements while concurrent History queries run. The delivered
// regression guard must observe and reject the intermediate half-batch
// snapshots.
func TestScratchHalfBatchIsCaught(t *testing.T) {
	dir := t.TempDir()
	seeder, _ := OpenStore(dir)
	existing, batch, _ := backfillRecords("scratch")
	if _, _, err := seeder.Submit(existing, testBase); err != nil {
		t.Fatal(err)
	}
	pre := seqSetOf(existing)
	post := seqSetOf(append(append([]Heartbeat{}, existing...), batch...))

	broken, err := OpenStore(dir)
	if err != nil {
		t.Fatal(err)
	}
	// Load the current file, then write it back three times, once per new
	// record — separate atomic replacements = three visible states.
	nf, err := loadNodeFile(broken.nodeLocationFor("scratch"))
	if err != nil {
		t.Fatal(err)
	}
	current := append([]Heartbeat{}, nf.Records...)

	stepReached := make(chan struct{}, 1)
	step := 0
	gate := make(chan struct{})
	orig := writeNodeFile
	writeNodeFile = func(path string, records []Heartbeat) error {
		step++
		if step <= len(batch) {
			stepReached <- struct{}{}
			<-gate
		}
		return orig(path, records)
	}
	t.Cleanup(func() { writeNodeFile = orig })

	// Drive the per-record writes manually with the real atomic writer.
	go func() {
		path := broken.nodePath("scratch")
		for _, r := range batch {
			current = append(current, r)
			if err := writeNodeFile(path, current); err != nil {
				t.Error(err)
				return
			}
		}
	}()

	var mu sync.Mutex
	var bad, total int
	stop := make(chan struct{})
	var wg sync.WaitGroup
	for i := 0; i < 6; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				reader, _ := OpenStore(dir)
				hist, qerr := reader.History("scratch")
				if qerr != nil {
					continue
				}
				total++
				if err := checkAtomicSnapshot(hist, pre, post); err != nil {
					mu.Lock()
					bad++
					mu.Unlock()
				}
			}
		}()
	}

	for step < len(batch) {
		<-stepReached
		time.Sleep(2 * time.Millisecond) // let readers sample the intermediate state
		gate <- struct{}{}
	}
	close(stop)
	wg.Wait()

	t.Logf("scratch: %d queries sampled, %d correctly identified as half-batch", total, bad)
	if bad == 0 {
		t.Fatal("guard FAILED TO DETECT a genuinely partial per-record commit")
	}
}

